// MDT decision matrix: tap what is known about the case; scenarios that no longer fit drop away.
// Markup is generated by build.py from mdt_data.py. Nothing is stored: each case starts blank.
(function(){
  var panels = document.querySelectorAll('.mdt-panel');
  if(!panels.length) return;
  function parse(s){ try{ return JSON.parse(s || '{}'); }catch(e){ return {}; } }
  panels.forEach(function(panel){
    var ins = Array.prototype.slice.call(panel.querySelectorAll('.mdt-in'));
    if(!ins.length) return;
    var ids = ins.map(function(i){ return i.dataset.m; });
    var active = ids[0];
    var state = {}; ids.forEach(function(id){ state[id] = {}; });
    function all(sel, m){ return Array.prototype.slice.call(panel.querySelectorAll(sel + '[data-m="' + m + '"]')); }

    function visible(field, sel){
      var show = field.dataset.show ? parse(field.dataset.show) : null;
      if(!show) return true;
      return show.some(function(cond){
        return Object.keys(cond).every(function(k){ return sel[k] && cond[k].indexOf(sel[k]) >= 0; });
      });
    }
    // when = list of {field: [options]}; the row fits if any one of them fits
    function fits(when, sel, strict){
      return when.some(function(w){
        return Object.keys(w).every(function(k){
          if(!sel[k]) return !strict;
          return w[k].indexOf(sel[k]) >= 0;
        });
      });
    }
    function render(){
      // which matrix is showing
      ids.forEach(function(id){
        var on = id === active;
        panel.querySelectorAll('[data-m="' + id + '"]').forEach(function(el){ el.classList.toggle('mdt-inactive', !on); });
      });
      panel.querySelectorAll('.mdt-pick').forEach(function(b){ b.setAttribute('aria-pressed', b.dataset.pick === active ? 'true' : 'false'); });
      var box = ins[ids.indexOf(active)], sel = state[active];
      var fields = Array.prototype.slice.call(box.querySelectorAll('.mdt-f'));
      // progressive disclosure: hide fields that do not apply yet, and forget their answers
      var changed = true, guard = 0;
      while(changed && guard++ < 10){
        changed = false;
        fields.forEach(function(f){
          var vis = visible(f, sel);
          f.hidden = !vis;
          if(!vis && sel[f.dataset.f]){ delete sel[f.dataset.f]; changed = true; }
        });
      }
      fields.forEach(function(f){
        f.querySelectorAll('.mdt-o').forEach(function(b){ b.setAttribute('aria-pressed', sel[f.dataset.f] === b.dataset.v ? 'true' : 'false'); });
      });
      // rows
      var rows = all('.mdt-row', active), shown = [], base = 0;
      rows.forEach(function(r){
        var strict = r.hasAttribute('data-strict');
        var ok = fits(parse(r.dataset.when), sel, strict);
        r.classList.toggle('mdt-off', !ok);
        r.classList.remove('mdt-hit');
        if(!strict) base++;
        if(ok) shown.push(r);
      });
      var main = shown.filter(function(r){ return !r.hasAttribute('data-strict'); });
      var any = Object.keys(sel).length > 0;
      if(any && main.length === 1) main[0].classList.add('mdt-hit');
      // group headings
      all('.mdt-grp', active).forEach(function(h){
        var g = h.dataset.g;
        h.classList.toggle('mdt-off', !shown.some(function(r){ return r.dataset.g === g; }));
      });
      // count and what to ask next
      var count = box.querySelector('.mdt-count');
      count.textContent = !any ? base + ' scenarios. Tap what is known.' :
        main.length === 0 ? 'No scenario fits this combination: discuss individually.' :
        main.length === 1 ? '1 scenario fits.' : main.length + ' of ' + base + ' scenarios fit.';
      var next = box.querySelector('.mdt-next'), ask = [];
      if(main.length > 1){
        fields.forEach(function(f){
          if(f.hidden || sel[f.dataset.f]) return;
          var k = f.dataset.f, n = f.querySelectorAll('.mdt-o').length;
          var splits = main.some(function(r){ return parse(r.dataset.when).some(function(w){ return w[k] && w[k].length < n; }); });
          if(splits) ask.push(f.querySelector('legend').textContent);
        });
      }
      next.hidden = !ask.length;
      next.textContent = ask.length ? 'Still to establish: ' + ask.join(' · ') : '';
      box.querySelector('.mdt-reset').disabled = !any;
    }
    function summary(){
      var box = ins[ids.indexOf(active)], sel = state[active], bits = [];
      box.querySelectorAll('.mdt-f').forEach(function(f){
        var v = sel[f.dataset.f]; if(!v) return;
        var b = f.querySelector('.mdt-o[data-v="' + v + '"]');
        bits.push(f.querySelector('legend').textContent + ': ' + (b ? b.textContent : v));
      });
      var out = [box.dataset.label + ' MDT', bits.join('; ') || 'No details entered'];
      all('.mdt-row', active).forEach(function(r){
        if(r.classList.contains('mdt-off')) return;
        var rec = r.querySelector('.rec dd');
        out.push('- ' + r.dataset.title.replace(/^MDT: /, '') + ': ' + (rec ? rec.textContent.replace(/\s+/g, ' ').trim() : ''));
      });
      return out.join('\n');
    }
    panel.addEventListener('click', function(e){
      var t = e.target.closest('button'); if(!t || !panel.contains(t)) return;
      if(t.classList.contains('mdt-o')){
        var f = t.closest('.mdt-f').dataset.f, sel = state[active];
        if(sel[f] === t.dataset.v) delete sel[f]; else sel[f] = t.dataset.v;
        render();
      } else if(t.classList.contains('mdt-reset')){
        state[active] = {}; render();
      } else if(t.classList.contains('mdt-pick')){
        active = t.dataset.pick; render();
      } else if(t.classList.contains('mdt-compact')){
        var on = panel.classList.toggle('mdt-compactview');
        panel.querySelectorAll('.mdt-compact').forEach(function(b){ b.setAttribute('aria-pressed', on ? 'true' : 'false'); });
      } else if(t.classList.contains('mdt-copy')){
        var txt = summary(), done = function(){ var o = t.textContent; t.textContent = 'Copied'; setTimeout(function(){ t.textContent = o; }, 1400); };
        var fallback = function(){ var ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); done(); }catch(x){} ta.remove(); };
        if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(txt).then(done, fallback); else fallback();
      }
    });
    render();
  });
})();
